// Generated from the individually edited RU event-outcomes catalog (E431-E500).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E431_E500 = Object.freeze({"E431.1":{"s":"За стеной открывается старый золотой схрон, а Торн нервно сверяет оставшиеся три метра. Шахтёры забирают находку до нового бурения.","f":"Едва бур проходит предупреждённую глубину, из прохода выходят вооружённые существа. Начинается битва."},"E431.2":{"s":"Вы поддерживаете шахтёров, и Торн запечатывает опасный забой до выяснения происхождения письма. Рабочие убирают инструменты."},"E431.3":{"s":"{{heroName}} закрепляет стену и находит рядом с трещиной кладку с золотом и припасами. Рабочие благодарят за безопасную проверку.","f":"Подпорка срывается, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Забой опасно оседает, но никто из подходящих бойцов не получает тяжёлого ранения. Проверка останавливается."}},"E431.4":{"s":"Вы покидаете шахту с первой сменой. Торн ещё раз читает письмо, датированное сегодняшним днём."},"E432.1":{"s":"Белм соглашается снять именной блок и сохранить его в семейном зале. Ремонтники платят золотом за спасённую арку.","f":"Белм требует оставить подпись на прежнем месте и запрещает работу. Трещина продолжает расширяться."},"E432.2":{"s":"Вы оставляете рабочим припасы на временные подпорки, а мастер выплачивает золото за срочную помощь."},"E432.3":{"s":"{{heroName}} снимает блок с надписью целиком и заменяет его новой опорой. Белм благодарит золотом за сохранённое имя Горака.","f":"Повреждённая арка проседает и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Арка опасно проседает, но никто из подходящих бойцов не получает тяжёлого ранения. Перенос подписи приходится отложить."}},"E432.4":{"s":"Вы уходите, оставив Белма охранять подпись предка. Из трещины над ним снова сыплется песок."},"E433.1":{"s":"Вы останавливаете обе печи, а рабочие перенаправляют воду мимо штолен. Кузнецы снабжают отряд припасами за предотвращённую беду.","f":"Гарн и Мора объявляют вмешательство нарушением соревнования и выводят сторонников на стычку."},"E433.2":{"s":"Вы выкупаете уголь и походные припасы до того, как ученики забрасывают всё в горны. На площади уже течёт ручей."},"E433.3":{"s":"{{heroName}} прокладывает отводной канал, и вода больше не заливает нижние шахты. Горняки платят золотом за спасённые выработки.","f":"Под натиском воды срывается крепление, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Поток повреждает временную защиту, но никто из подходящих бойцов не получает тяжёлого ранения. Штольни остаются под угрозой."}},"E433.4":{"s":"Вы уходите на высоту, пока Гарн и Мора спорят, чей горн первым расплавил площадь. Аварийные колокола звучат всё громче."},"E434.1":{"s":"Новая тропа приводит к оставленному запасу еды, а палец статуи указывает туда же. Хранитель Дул не решается назвать это совпадением.","f":"За поворотом туманной тропы выходят вооружённые налётчики. Начинается стычка."},"E434.2":{"s":"Вы выбираете проверенную дорогу и тратите дополнительные припасы на длинный переход. Статуя остаётся указывать в туман."},"E434.3":{"s":"{{heroName}} находит на новой тропе безопасный спуск и тайник с припасами. Караванщики благодарят за разведку.","f":"На незнакомом склоне {{affectedHeroName}} получает тяжёлое ранение от обвала.","v":{"nf":"Обвал останавливает разведку, но никто из подходящих бойцов не получает тяжёлого ранения. Новый путь остаётся непроверенным."}},"E434.4":{"s":"Вы позволяете первому каравану сделать выбор за себя. Дул всё ещё смотрит на палец древнего проводника."},"E435.1":{"s":"Вы оплачиваете пошлину, рассчитанную по странному сравнению плаща с бородой. Чиновник с облегчением выпускает отряд."},"E435.2":{"s":"Вы указываете, что закон не определяет бороду как обязательное условие проезда. Чиновник возвращает золото за неверный тариф.","f":"Чиновник считает конский хвост допустимой меркой и взыскивает золото за возражение."},"E435.3":{"s":"{{heroName}} находит в старых правилах освобождение путников без бороды от сбора. Казна получает возвращённое золото.","f":"{{heroName}} не находит исключения, а за архивную проверку приходится платить. Казна теряет золото."},"E435.4":{"s":"Вы тратите припасы на внешнюю дорогу и оставляете чиновника измерять длину чужого плаща."},"E436.1":{"s":"Вы вытаскиваете рабочего из-под обломков, и комиссия благодарит золотом за спасение. Фрам записывает новый показатель нагрузки.","f":"Во время разборки падает плита, тяжело раня {{affectedHeroName}}.","v":{"nf":"Обломки опасно сдвигаются, но никто из подходящих бойцов не получает тяжёлого ранения. Рабочего пока не достать."}},"E436.2":{"s":"Вы выделяете припасы спасательной смене, и комиссия выплачивает золото за помощь. Из-под завала доносится просьба не спорить до спасения."},"E436.3":{"s":"{{heroName}} закрепляет уцелевшие балки, позволив рабочим выбраться. Комиссия платит золотом за спасённые жизни.","f":"Оставшаяся опора ломается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Опора обрушивается, но никто из подходящих бойцов не получает тяжёлого ранения. Завал приходится оставить до подкрепления."}},"E436.4":{"s":"Вы покидаете стройку до следующего эксперимента. Фрам продолжает доказывать, что обрушение произошло исключительно по расчёту."},"E437.1":{"s":"Лем соглашается расторгнуть договор, а Эзрак платит золото за возвращённую независимость. Демон впервые благодарит писаря без угроз.","f":"Другие демоны объявляют расторжение нарушением адского устава и выходят на стычку."},"E437.2":{"s":"Эзрак платит золотом за короткую консультацию, и вы оставляете его выполнять обязанности у Лема."},"E437.3":{"s":"{{heroName}} находит пункт о взаимном согласии и оформляет расторжение без новых обязательств. Эзрак выдаёт золото за спасённую свободу.","f":"Адский архив находит платное исключение для ошибок писаря, и отряду приходится отдать золото."},"E437.4":{"s":"Вы уходите, оставив Эзрака в подчинении у Лема. Писарь уже собирается поручить демону перебрать чернильницы."},"E438.1":{"s":"Вы убеждаете Кхароса перестать командовать собственным отдыхом и просто закрыть глаза. Утром трактирщик благодарит золотом за тихую ночь.","f":"Демон требует официального подтверждения сна каждые несколько минут. Отдохнуть не удаётся никому."},"E438.2":{"s":"Вы продаёте трактирщику припасы для бессонной смены, а он платит золотом. С верхнего этажа вновь звучит «Я РАССЛАБЛЕН!»"},"E438.3":{"s":"{{heroName}} проводит обряд тишины, после которого Кхарос хотя бы перестаёт кричать. Трактирщик благодарит золотом.","f":"Ритуал вызывает резкий магический отклик, тяжело раня {{affectedHeroName}}.","v":{"nf":"Ритуал срывается от опасного отклика, но никто из подходящих бойцов не получает тяжёлого ранения. Кхарос по-прежнему не спит."}},"E438.4":{"s":"Вы выбираете другой трактир. Даже на улице слышно, как Кхарос настойчиво пытается заснуть."},"E439.1":{"s":"Вы ведёте Тика на знакомый рёв, и к нему подбегает мать, которая мгновенно перестаёт сердиться. Ярмарочные торговцы делятся припасами.","f":"На шум приходят вооружённые демоны, принимающие вас за похитителей бесёнка. Начинается стычка."},"E439.2":{"s":"Вы оставляете Тику припасы и показываете дорогу к ярмарке. Бесёнок старается не плакать искрами на сухую траву."},"E439.3":{"s":"{{heroName}} быстро находит на ярмарке сердитую красную демоницу, которая узнаёт клич Тика. Она благодарит золотом за возвращённого сына.","f":"На ярмарке {{affectedHeroName}} попадает под удар встревоженной охраны и получает тяжёлое ранение.","v":{"nf":"Ярмарочная охрана срывает поиски, но никто из подходящих бойцов не получает тяжёлого ранения. Мать пока не найдена."}},"E439.4":{"s":"Вы уезжаете, оставив Тика ждать знакомого рёва за холмом. Трава возле него снова вспыхивает от всхлипа."},"E440.1":{"s":"Ракс признаёт выбор Пушка и отступает от монастыря. Благодарные монахи делятся припасами.","f":"Демон требует боевого пса обратно и зовёт вооружённых прислужников. Начинается стычка."},"E440.2":{"s":"Вы отдаёте Раксу золото, и он оставляет Пушка монахам. Те благодарят припасами за мирный договор.","f":"Ракс отказывается считать золото заменой своему зверю. Пёс остаётся у монастыря, спор не прекращается."},"E440.3":{"s":"Вы предлагаете Раксу навещать Пушка без права уводить его силой. Демон соглашается и платит золотом за решение.","f":"Ракс принимает договор за насмешку и зовёт прислужников. Начинается стычка."},"E440.4":{"s":"Вы не вмешиваетесь в выбор трёхглазого пса. Пушок спокойно ложится у монастырских ворот, а Ракс остаётся с пустым поводком."},"E441.1":{"s":"Вы выводите Марта из очереди с документом об отмене договора, а он благодарит золотом за возвращённую душу.","f":"Адские приставы требуют новую подпись и выходят задерживать отряд. Начинается стычка."},"E441.2":{"s":"Вы уплачиваете канцелярский сбор, и Фес окончательно закрывает дело Марта. Старик благодарит припасами за спасённое время."},"E441.3":{"s":"{{heroName}} доказывает, что аннулированный договор нельзя восстановить принудительной подписью. Фес возвращает золото за незаконный сбор.","f":"Архив находит старую пошлину за отмену, и казна теряет золото. Март продолжает ждать окончательного решения."},"E441.4":{"s":"Вы покидаете адскую канцелярию до просьбы показать подпись Короля. Март бережно держит бумагу о возвращённой душе."},"E442.1":{"s":"Вы удерживаете Орда от удара и позволяете отражению объяснить, чем оно отличается от хозяина. Двойник благодарит золотом за спасённое зеркало.","f":"Настоящий демон зовёт вооружённых помощников разбить своё отражение. Начинается стычка."},"E442.2":{"s":"Вы уносите зеркало из комнаты, а отражение благодарит вас за аккуратность. Хозяин выдаёт припасы за помощь.","f":"Стекло оборачивается острым краем и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Зеркало опасно трескается, но никто из подходящих бойцов не получает тяжёлого ранения. Переноску останавливают."}},"E442.3":{"s":"{{heroName}} обнаруживает, что отражение повторяет забытые вежливые слова самого Орда. Демон платит золотом за объяснение.","f":"Зеркало отвечает на осмотр магическим ударом, тяжело раня {{affectedHeroName}}.","v":{"nf":"Отражение срывает проверку опасным всплеском, но никто из подходящих бойцов не получает тяжёлого ранения. Его природа остаётся неясной."}},"E442.4":{"s":"Вы оставляете Орда спорить с более вежливым собой. Отражение извиняется за него даже на прощание."},"E443.1":{"s":"Вы передаёте Пика стражникам, не позволяя ему спрятаться за ангельской охраной. Саэль благодарит золотом за исправленную ошибку.","f":"Пик зовёт подельников, чтобы защитить свои три года небесного покровительства. Начинается стычка."},"E443.2":{"s":"Вы покупаете у Томена хлеб для дороги. Саэль впервые внимательно читает имя на вывеске пекарни."},"E443.3":{"s":"{{heroName}} находит два одинаковых имени в старой ведомости и предлагает Саэлю подать официальное исправление. Ангел платит золотом.","f":"{{heroName}} не находит способа изменить трёхлетнее назначение без публичного разбора. Саэль остаётся в растерянности."},"E443.4":{"s":"Вы оставляете Саэля разбираться с карманником и настоящим пекарем. Пик уже спрашивает, можно ли продлить защиту."},"E444.1":{"s":"Вы сушите молитвы и находите адресатов по именам в сохранившихся строках. Риэль благодарит припасами за восстановленный мешок.","f":"Чернила растеклись слишком сильно, и большую часть свитков приходится отложить. Курьер остаётся с чужими просьбами."},"E444.2":{"s":"Вы отдаёте Риэлю припасы на дорогу, а он платит золотом за возможность завершить доставку."},"E444.3":{"s":"{{heroName}} сопоставляет содержание молитв с местными семьями и возвращает каждому нужный свиток. Курьер благодарит золотом.","f":"{{heroName}} ошибочно сводит две похожие просьбы, и за исправление канцелярия взыскивает золото."},"E444.4":{"s":"Вы не читаете чужие молитвы больше необходимого. Девочка продолжает серьёзно изучать приказ о крепостной стене."},"E445.1":{"s":"Вы встаёте между всадниками и амбаром, не давая им обыскать укрытие. Элиар благодарит золотом за защищённых людей.","f":"Преследователи требуют пропустить их и выхватывают оружие. Начинается стычка."},"E445.2":{"s":"Вы отдаёте семье припасы и выводите беглецов через задний двор до прибытия всадников. Элиару не приходится отвечать на их вопрос."},"E445.3":{"s":"{{heroName}} отвечает на вопросы о правах всадников, не позволяя им спросить Элиара о беглецах. Ангел благодарит золотом.","f":"Преследователи понимают уловку и берутся за оружие. Начинается стычка."},"E445.4":{"s":"Вы оставляете Элиара решить, как говорить правду и никого не выдавать. На дороге уже слышны копыта."},"E446.1":{"s":"Жители соглашаются снять ложный образ непобедимого воина, а Алмер платит золотом за право не быть памятником самому себе.","f":"Ангел запрещает демонтаж освящённой статуи, и просьба Алмера остаётся без ответа."},"E446.2":{"s":"Вы оплачиваете переделку памятника, заменив меч лекарской сумкой. Горожане благодарят припасами за сохранённый образ без лжи."},"E446.3":{"s":"Ангел признаёт, что воля живого Алмера важнее удобной легенды, и город платит золотом за согласованное решение.","f":"Хранитель считает освящение необратимым и не принимает слов самого Алмера. Памятник остаётся прежним."},"E446.4":{"s":"Вы уходите, оставляя целителя Алмера спорить с собственной статуей в доспехах. На площади уже продают игрушечные мечи святого."},"E447.1":{"s":"Нора выигрывает следующую партию без единой уловки, и ставка приносит отряду золото. Фаэль требует ещё одну игру.","f":"Фаэль наконец угадывает ход Норы, и ваша ставка остаётся у распорядителя."},"E447.2":{"s":"Вы убеждаете Фаэля признать умение девочки, а не искать ещё один реванш. Родители благодарят припасами.","f":"Ангел объявляет проигрыш неразрешённой загадкой и снова раскладывает камешки. Он не готов остановиться."},"E447.3":{"s":"{{heroName}} неожиданно находит выигрышную комбинацию против Норы, и зрители расплачиваются золотом.","f":"Нора обыгрывает {{heroName}} за три хода и забирает поставленное золото."},"E447.4":{"s":"Вы уходите до того, как Фаэль составит турнирную сетку для местных детей. Нора уже готовит камешки для следующего соперника."},"E448.1":{"s":"Вы передаёте разбойника страже, чтобы наказание решал суд, а не дорога. Ориэль благодарит золотом за законное решение.","f":"Касс считает задержание отказом от милосердия, и ангелы не дают увести пленника. Спор продолжается."},"E448.2":{"s":"Вы поддерживаете Касса, и разбойник быстро уходит с дороги, не дожидаясь новых богословских доводов. Ориэль остаётся недоволен."},"E448.3":{"s":"{{heroName}} предлагает суд и обязанность возместить вред без расправы. Оба ангела признают это милосердием с ответственностью и платят золотом.","f":"{{heroName}} не может согласовать, кому поручить контроль за обещанием разбойника. Ангелы продолжают спор."},"E448.4":{"s":"Вы оставляете ангелов определять милосердие в присутствии заинтересованного разбойника. Тот уже предлагает третий вариант — немедленно его отпустить."},"E449.1":{"s":"Вы выносите свитки в чистый воздух, пока Ксар старается не чихать на родословные. Архивист благодарит золотом.","f":"Внезапный огненный чих тяжело ранит {{affectedHeroName}}.","v":{"nf":"Огненный чих срывает эвакуацию, но никто из подходящих бойцов не получает тяжёлого ранения. Свитки остаются под угрозой."}},"E449.2":{"s":"Вы отдаёте архивистам переносные светильники и припасы, а Ксар платит золотом за возможность погасить факелы."},"E449.3":{"s":"{{heroName}} прочищает старый дымоход, и воздух в пещере становится безопаснее для свитков. Рина благодарит золотом и припасами.","f":"Старая заслонка срывается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Вентиляция опасно обрушивается, но никто из подходящих бойцов не получает тяжёлого ранения. Работу прекращают."}},"E449.4":{"s":"Вы оставляете Ксара воевать с дымом и собственными чихами. Рина тушит ещё один факел."},"E450.1":{"s":"Саар отвлекает птенца знакомым зовом, и тот возвращается в святилище. Жрица делится припасами за помощь.","f":"Птенец продолжает ползти за Королём, не реагируя на жрицу. Обряд наставничества остаётся неразрешённым."},"E450.2":{"s":"Вы отдаёте Саар припасы на корм птенцу, а она благодарит золотом за заботу."},"E450.3":{"s":"Король остаётся наставником на короткий обряд, и птенец наконец слушает голос жрицы. Саар благодарит золотом за терпение.","f":"Испуганный птенец случайно обжигает Короля, причиняя тяжёлое ранение.","v":{"nf":"Птенец пугается и выпускает огонь, но Король не получает тяжёлого ранения. Обряд приходится отложить."}},"E450.4":{"s":"Вы уходите от святилища до нового решения жрицы. Позади слышно довольное урчание птенца, выбравшего Короля."},"E451.1":{"s":"Веша зажигает переносную лампу от родового очага и признаёт, что предки берегли сам огонь, а не его стены. Переселенцы благодарят припасами.","f":"Старейшины требуют оставить пламя в прежнем камне, и Веша не решается нарушить обычай. Отъезд задерживается."},"E451.2":{"s":"Вы передаёте переселенцам провизию, а старейшины благодарят золотом за помощь с долгой дорогой."},"E451.3":{"s":"{{heroName}} проводит обряд сохранения пламени в новой жаровне, и Веша принимает перенос. Поселение награждает золотом.","f":"При переносе очага старый камень раскалывается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Камень очага срывается с основания, но никто из подходящих бойцов не получает тяжёлого ранения. Обряд останавливают."}},"E451.4":{"s":"Вы оставляете Вешу у трёхсотлетнего огня. Склон над пустеющими домами продолжает осыпаться."},"E452.1":{"s":"Вы открываете засорившийся горячий канал, и ледяная корка начинает таять. Клан снабжает отряд припасами за помощь.","f":"Подо льдом вырывается струя горячего пара и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Пар срывает расчистку, но никто из подходящих бойцов не получает тяжёлого ранения. Купальня остаётся замёрзшей."}},"E452.2":{"s":"Вы продаёте клану топливо и припасы, а Ро выплачивает золото за возможность обогреть купальню."},"E452.3":{"s":"{{heroName}} находит холодную печать под дном и освобождает путь к горячему источнику. Старейшина благодарит золотом и припасами.","f":"Ледяная печать отвечает ударом, тяжело раня {{affectedHeroName}}.","v":{"nf":"Печать отталкивает исследователей, но никто из подходящих бойцов не получает тяжёлого ранения. Источник холода не установлен."}},"E452.4":{"s":"Вы уходите, не объясняя драконидам назначение льда. Ро всё ещё считает замёрзшую купальню личным оскорблением."},"E453.1":{"s":"Вы выбираете самую убедительную невозможную историю, а Иара наконец разрешает площади смеяться. Клан платит золотом за справедливое судейство.","f":"Иара объявляет, что лучший лжец должен прежде всего знать меру, и отказывается принимать ваш выбор. Турнир продолжается."},"E453.2":{"s":"Иара признаёт третью речь блестящей ложью, а ваши деньги приносят золотой выигрыш.","f":"Иара не смеётся над комплиментом и назначает другого победителя. Ставка остаётся у распорядителей."},"E453.3":{"s":"{{heroName}} рассказывает историю, которой слушатели хотят поверить вопреки очевидному абсурду. За выступление клан вручает золото.","f":"Иара замечает неудачное преувеличение, и за нарушение условий конкурса приходится отдать золото."},"E453.4":{"s":"Вы покидаете площадь до решения Иары. Третий участник всё ещё объясняет, что не хотел лгать настолько откровенно."},"E454.1":{"s":"Вы находите у замков поджигателя, переносившего огонь по дверным рунам. Кер выплачивает золото за его задержание.","f":"Пойманный поджигатель зовёт вооружённых помощников из-за амбара. Начинается стычка."},"E454.2":{"s":"Вы выносите мешки зерна через проход без горящих замков и пополняете припасы отряда.","f":"Дверной механизм вспыхивает при спасении, тяжело раня {{affectedHeroName}}.","v":{"nf":"Пламя перекрывает вход, но никто из подходящих бойцов не получает тяжёлого ранения. Зерно остаётся внутри."}},"E454.3":{"s":"{{heroName}} замечает, кто переходит от двери к двери с зажигательной печатью, и находит при нём золото. Кер благодарит за разоблачение.","f":"В погоне по крыше {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Преследование останавливается на опасном участке, но никто из подходящих бойцов не получает тяжёлого ранения. Поджигатель исчезает."}},"E454.4":{"s":"Вы покидаете амбар до следующей вспыхнувшей двери. Кер всё ещё пытается понять, почему влажное зерно не горит."},"E455.1":{"s":"Вы напоминаете стае, что луна не обязана являться в качестве обвиняемой и не отвечает за облака. Неша благодарит припасами за защиту.","f":"Рагар настаивает, что отсутствие луны доказывает умышленное уклонение. Суд не принимает довод."},"E455.2":{"s":"Вы предлагаете символический штраф небесному светилу, и клан платит золотом за смешное завершение спора.","f":"Неша считает подобный приговор унижением священной луны, и её сторонники начинают стычку."},"E455.3":{"s":"{{heroName}} показывает волкам чередование фаз, не оспаривая их право задавать вопросы. Рагар благодарит золотом за объяснение.","f":"Стая отказывается принимать календарь вместо явки обвиняемой. Суд продолжает заседать."},"E455.4":{"s":"Вы покидаете суд до вынесения приговора луне. Над поляной ещё светло, что обвинение считает подозрительным."},"E456.1":{"s":"Вы поднимаете заклинившую створку как раз перед бегущим Харом. Почтальон пролетает через проём и оставляет золотую благодарность.","f":"Тяжёлая створка срывается с петель, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Ворота опасно падают, но никто из подходящих бойцов не получает тяжёлого ранения. Хару приходится искать другой путь."}},"E456.2":{"s":"Вы расходуете припасы на разбор баррикады, и Хар успевает проскочить по свободной полосе. Смотритель выплачивает золото за помощь."},"E456.3":{"s":"{{heroName}} высвобождает сломанный стопор и открывает ворота до столкновения. Смотритель благодарит золотом.","f":"Механизм бьёт обратным ходом, тяжело раня {{affectedHeroName}}.","v":{"nf":"Створки опасно дёргаются, но никто из подходящих бойцов не получает тяжёлого ранения. Механизм остаётся заклиненным."}},"E456.4":{"s":"Вы отходите от дороги, пока Хар приближается к заставе. Смотритель продолжает кричать, что ремонт займёт десять минут."},"E457.1":{"s":"Мер без труда вспоминает каждую подробность жизни Аши, кроме её имени, и семья понимает, что память исчезла избирательно. В благодарность вам дают припасы.","f":"Мер пугается дальнейших вопросов и просит прекратить проверку. Родным пока нечем его успокоить."},"E457.2":{"s":"Вы даёте семье припасы на дорогу к целителю, а Аша благодарит золотом за возможность найти помощь."},"E457.3":{"s":"{{heroName}} замечает на старом семейном обереге повреждённую руну имени. Мер узнаёт её и благодарит золотом за находку.","f":"Печать имени отвечает опасным ударом, тяжело раня {{affectedHeroName}}.","v":{"nf":"Оберег срывает проверку, но никто из подходящих бойцов не получает тяжёлого ранения. Имя Мер так и не вспомнил."}},"E457.4":{"s":"Вы оставляете Мера наедине с дочерью, не превращая забытое имя в публичное испытание. Аша берёт отца за руку."},"E458.1":{"s":"Вы подтверждаете, что Вира предупреждает покупателей о лжи заранее. Стражник отступает, а лисица благодарит золотом.","f":"Стражник считает услугу намеренным введением людей в заблуждение и отказывается отпускать Виру. Спор продолжается."},"E458.2":{"s":"Вы заказываете Вире убедительную ложь, а затем распознаёте её при зрителях и получаете золотой выигрыш.","f":"Вира находит такую правдоподобную неправду, что вы не можете её опровергнуть. Оплата остаётся у лисицы."},"E458.3":{"s":"{{heroName}} ловит Виру на фразе, где она скрыла сам факт лжи. За разоблачение лисица платит золотом.","f":"Вира доказывает, что предупредила о каждом вымысле, и {{heroName}} оплачивает проигранный спор золотом."},"E458.4":{"s":"Вы уходите, не покупая ложь с гарантийной печатью. Вира уже обещает следующему клиенту особенно честный обман."},"E459.1":{"s":"Совет соглашается, что победа в поединке не равна желанию править. Архан благодарит отряд припасами за свободу выбора.","f":"Старейшины требуют буквального исполнения традиции и не освобождают Архана от должности."},"E459.2":{"s":"Мейра рассказывает о запасах и союзниках, и совет признаёт её подходящей главой клана. Семья благодарит золотом.","f":"Сторонники силы объявляют разговор о торговых путях оскорблением клана и начинают стычку."},"E459.3":{"s":"Архан охотно выбирает службу в походе вместо трона, к которому не стремился. Лев присоединяется к отряду.","f":"Архан отказывается уходить, пока совет не решит вопрос преемника. Нанять его не удаётся.","v":{"rs":"Архан согласен отправиться с Королём, но взять нового бойца невозможно. Он благодарит золотом за предложение."}},"E459.4":{"s":"Вы оставляете львиному клану право назначить собственного вождя. Мейра всё ещё ждёт, когда её попросят выступить."},"E460.1":{"s":"Вы убеждаете Барра принять свой мешок и закрыть дело о краже. Купец благодарит золотом за окончание тревожной истории.","f":"Барр отказывается брать монеты, которые меняют число сами собой. Нис продолжает просить избавить её от мешка."},"E460.2":{"s":"Нис соглашается уйти с отрядом, не желая больше слышать стук из пустой комнаты. Она становится новым спутником.","f":"Нис не может заставить себя уйти, не узнав, кто стучал у неё за спиной. Нового бойца нет.","v":{"rs":"Нис согласна уйти, но в отряде нет места. Она благодарит золотом за попытку помочь."}},"E460.3":{"s":"{{heroName}} находит в мешке чужую счётную печать, меняющую показания монет. Барр награждает золотом за найденную причину.","f":"Печать вспыхивает в руках исследователя, тяжело раня {{affectedHeroName}}.","v":{"nf":"Мешок отвечает опасной вспышкой, но никто из подходящих бойцов не получает тяжёлого ранения. Происхождение стука остаётся неизвестным."}},"E460.4":{"s":"Вы не касаетесь золота, от которого отказалась сама воровка. Барр смотрит на мешок так, будто тот может снова постучать."},"E461.1":{"s":"Вы показываете В-12, что приказ Элга допускает открытие ворот после проверки. Голем пропускает караван, а мастер платит золотом.","f":"В-12 выбирает строгое толкование без запятой и вызывает вооружённую охрану. Начинается стычка."},"E461.2":{"s":"Вы обходите воображаемо закрытый проезд, тратя припасы на длинную дорогу. Голем продолжает требовать запятую."},"E461.3":{"s":"{{heroName}} составляет новый приказ без двусмысленности, и В-12 наконец пропускает телеги. Элг благодарит золотом.","f":"Голем обнаруживает противоречие между старым и новым приказами и отказывается их согласовать. Проход остаётся закрытым."},"E461.4":{"s":"Вы оставляете караван спорить о запятой. В-12 аккуратно добавляет ещё одну возможную интерпретацию в журнал."},"E462.1":{"s":"Вы останавливаете К-22, освобождая склад от бессмысленного производства. Дин благодарит золотом за наконец свободный проход.","f":"К-22 объявляет остановку нарушением действующего приказа и поднимает охранные механизмы. Начинается стычка."},"E462.2":{"s":"Вы покупаете у склада металл и припасы, пока К-22 штампует очередную ненужную шестерню."},"E462.3":{"s":"{{heroName}} находит в старом заказе утраченную часть с настоящим назначением детали. Дин платит золотом за разгадку.","f":"{{heroName}} не может восстановить имя заказчика, а склад взыскивает расходы на архивную проверку. Казна теряет золото."},"E462.4":{"s":"Вы оставляете К-22 делать детали для неизвестной машины. Дин уже ищет место под новый зал хранения."},"E463.1":{"s":"Вы проходите на месте несуществующих ворот, и А-11 не успевает распознать нарушение. Жители впервые видят прямой путь через старую арку.","f":"Страж объявляет проход без документа незаконным и поднимает вооружённую защиту. Начинается стычка."},"E463.2":{"s":"Вы проходите посёлок вместе с жителями в обход старого поста, потратив немного провизии на крюк."},"E463.3":{"s":"{{heroName}} отключает устаревший приказ, не повредив А-11, и освобождает дорогу. Посёлок благодарит золотом.","f":"Защитные сочленения захлопываются и тяжело ранят {{affectedHeroName}}.","v":{"nf":"Страж опасно срабатывает, но никто из подходящих бойцов не получает тяжёлого ранения. Пост остаётся активным."}},"E463.4":{"s":"Вы не объясняете А-11, что город исчез шестьдесят лет назад. Он останавливает очередного прохожего в пустом проёме."},"E464.1":{"s":"Вы признаёте обоих И-4 самостоятельными, и мастерская перестаёт искать того, кого нужно уничтожить. Работники благодарят припасами.","f":"Один из И-4 не принимает решение без доказательства собственного происхождения. Спор продолжается."},"E464.2":{"s":"Один из И-4 выбирает новую службу и вступает в королевский отряд. Второй желает ему найти собственные воспоминания.","f":"Оба И-4 предпочитают остаться вместе до выяснения их истории. Нанять одного не удаётся.","v":{"rs":"Один из И-4 согласен вступить в отряд, но свободного места нет. Мастерская благодарит золотом за предложение."}},"E464.3":{"s":"{{heroName}} убеждает автоматы, что одинаковая память не отменяет различий их будущего. Мастерская платит золотом за разрешённый спор.","f":"{{heroName}} не может убедить автоматы отказаться от поиска первого экземпляра. Они требуют проверить копирующее устройство снова."},"E464.4":{"s":"Вы не предлагаете молоток как решение спора о личности. Оба И-4 продолжают спорить, кто появился вчера."},"E465.1":{"s":"Вы разбиваете отряд на маленькие группы, и автомат считает каждую не больше десяти. Мост пропускает всех по очереди.","f":"Датчик замечает вторую тень одного из путников, и на ожидание приходится тратить припасы."},"E465.2":{"s":"Вы платите за ручной пропуск, и сборщик отключает двойной подсчёт на время перехода."},"E465.3":{"s":"{{heroName}} затеняет датчик так, чтобы тот видел только тела. Сборщик возвращает золото за ненужную пошлину.","f":"Автомат объявляет вмешательство нарушением правил и вызывает вооружённую стражу моста. Начинается стычка."},"E465.4":{"s":"Вы тратите припасы на дальнюю переправу. Мост продолжает считать тени отдельными путешественниками."},"E466.1":{"s":"Вы объясняете С-3 и остальным, что страх не запрещает выбирать действие, а лишь требует осторожности. Машины соглашаются попробовать, и Рен благодарит припасами.","f":"Автоматы считают вероятность поломки слишком высокой и не включаются. Рен оставляет инструменты на столе."},"E466.2":{"s":"Вы отдаёте Рену припасы для исследования, а он платит золотом за возможность учить машины дальше."},"E466.3":{"s":"С-3 решает узнать смелость в настоящем путешествии и вступает в отряд по собственному выбору.","f":"С-3 не готов покинуть своих товарищей, которые впервые узнали страх. Нанять его не удаётся.","v":{"rs":"С-3 готов к походу, но свободного места нет. Рен благодарит золотом за доверие."}},"E466.4":{"s":"Вы оставляете машины сами решать, как жить с новым знанием о поломке. С-3 продолжает размышлять о смелости."},"E467.1":{"s":"Вы бросаете пять монет в ведро, и медведь спокойно освобождает тропу. Торговцы позади вздыхают с облегчением."},"E467.2":{"s":"Медведь принимает припасы вместо монет и отходит от дороги, пропуская отряд.","f":"Зверь решает, что еда не заменяет блестящую плату, и бросается защищать ведро. Начинается стычка."},"E467.3":{"s":"{{heroName}} проводит отряд вдоль края тропы, пока медведь разглядывает пустое ведро. Никто не платит монет.","f":"Медведь резко разворачивается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Медведь преграждает проход, но никто из подходящих бойцов не получает тяжёлого ранения. Обход приходится искать снова."}},"E467.4":{"s":"Вы тратите припасы на обход звериного поста. Вдали медведь снова толкает ведро к следующему путнику."},"E468.1":{"s":"Вы добираетесь до колокольни и возвращаете семье свадебное кольцо, а среди вороньих сокровищ находите золото.","f":"На скользкой крыше {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Подъём срывается на опасной кровле, но никто из подходящих бойцов не получает тяжёлого ранения. Кольцо остаётся у ворона."}},"E468.2":{"s":"Ворон меняет кольцо на оставленную еду и бросает следом несколько чужих монет. Семья благодарит золотом за возвращённую святыню.","f":"Птица забирает еду, но кольцо оставляет в гнезде. На этом обмен заканчивается."},"E468.3":{"s":"{{heroName}} поднимается к гнезду, пока ворон наблюдает за поминальной процессией, и достаёт кольцо вместе с золотом.","f":"Ворон атакует у гнезда, тяжело раня {{affectedHeroName}}.","v":{"nf":"Птица срывает попытку забрать кольцо, но никто из подходящих бойцов не получает тяжёлого ранения. Добыча остаётся на колокольне."}},"E468.4":{"s":"Вы оставляете семье договариваться с вороном на крыше. Жрец всё ещё держит руку вытянутой, словно птица вот-вот вернётся."},"E469.1":{"s":"По следу лошади вы находите раненого курьера и его кошель с золотом у северной тропы. Хозяин благодарит за спасение.","f":"На северной дороге вас встречают вооружённые налётчики, задержавшие курьера. Начинается стычка."},"E469.2":{"s":"Вы даёте хозяину припасы для поисков, а он благодарит золотом и седлает запасную лошадь."},"E469.3":{"s":"{{heroName}} следует за тревожным поведением лошади и находит курьера вместе с дорожной казной. За спасение отряд получает золото.","f":"В засаде налётчиков {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Поиски наталкиваются на вооружённую засаду, но никто из подходящих бойцов не получает тяжёлого ранения. Курьер пока не найден."}},"E469.4":{"s":"Вы оставляете местным поиски курьера и продолжаете путь. Лошадь не даёт снять с себя окровавленное седло."},"E470.1":{"s":"Вы открываете проход воде, не разрушая всю плотину, и мельница снова поворачивает колесо. Том благодарит припасами.","f":"Огромное бревно срывается из плотины и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Плотина опасно сдвигается, но никто из подходящих бойцов не получает тяжёлого ранения. Мельница остаётся без воды."}},"E470.2":{"s":"Вы покупаете у Тома уцелевшие припасы, пока выдра на плотине внимательно следит за людьми."},"E470.3":{"s":"{{heroName}} строит отвод так, чтобы мельница получала воду, а выдры сохранили дом. Том платит золотом и отдаёт припасы.","f":"При ремонте обрушивается насыпь, тяжело раня {{affectedHeroName}}.","v":{"nf":"Насыпь срывается, но никто из подходящих бойцов не получает тяжёлого ранения. Перепускной канал не готов."}},"E470.4":{"s":"Вы оставляете Тома встречать следующую выдриную строительную смену. На вершине плотины уже закреплена новая доска."},"E471.1":{"s":"Вы обходите ближайшую гостиницу и тратите лишние припасы на ночную стоянку. У её закрытых дверей действительно раздаются три удара."},"E471.2":{"s":"Вы ночуете привычным маршрутом, не услышав трёх ударов, и хозяин делится припасами. Сова так и не появляется.","f":"После третьего удара у гостиницы выходят вооружённые незнакомцы. Начинается стычка."},"E471.3":{"s":"Вы следуете за белой совой до забытого укрытия и находите там золотые монеты. Птица исчезает над лесом.","f":"Сова уводит отряд слишком далеко, и на поиски обратной дороги уходят припасы."},"E471.4":{"s":"Вы оставляете письмо при себе, не меняя путь. Сова ещё некоторое время летит за Королём, словно ожидая решения."},"E472.1":{"s":"Вы отгоняете кабана от сундука, и кладоискатели передают вам золото из найденного клада.","f":"Кабан защищает выкопанный сундук, а разгорячённые искатели берутся за оружие. Начинается стычка."},"E472.2":{"s":"Кабан идёт за едой и оставляет крышку свободной. Кладоискатели расплачиваются золотом за ловкую приманку.","f":"Зверь забирает приманку и возвращается прямо на сундук. Кладоискатели остаются без доступа к кладу."},"E472.3":{"s":"{{heroName}} уводит кабана к трюфелям, не тревожа его, а кладоискатели достают золото и делятся наградой.","f":"Кабан разворачивается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Зверь срывает манёвр, но никто из подходящих бойцов не получает тяжёлого ранения. Сундук остаётся под ним."}},"E472.4":{"s":"Вы оставляете кабана на сундуке, который он нашёл быстрее трёх искателей. Зверь устраивается удобнее на крышке."},"E473.1":{"s":"Лисса признаёт, что перепутала годы в журнале доставки, и платит золото за исправленную ведомость. Хорм всё ещё держит приглашение на давно состоявшуюся свадьбу.","f":"Фея называет восьмидесятилетнее опоздание обычным сезонным сбоем и не предлагает объяснений. Разговор заканчивается."},"E473.2":{"s":"Вы покупаете у феи припасы, которые она носила вместе с письмами, и проверяете, пригодны ли они к дороге."},"E473.3":{"s":"{{heroName}} сравнивает семейные имена и выясняет, что приглашение предназначалось покойному тёзке Хорма. Лисса благодарит золотом.","f":"{{heroName}} не находит второго адресата, а фея взыскивает плату за розыск старой почты. Казна теряет золото."},"E473.4":{"s":"Вы поздравляете семью с давней свадьбой и уходите. Цветы на печати всё ещё раскрываются на солнце."},"E474.1":{"s":"Вы доказываете, что сон не становится платным без согласия спящего, и Тилла возвращает незаконно взятое золото.","f":"Фея зовёт защитников своего зелёного дворца и требует плату даже за спор. Начинается стычка."},"E474.2":{"s":"Вы отдаёте Тилле золото и прекращаете спор о ночи в чужом сне. Она торжественно выдаёт квитанцию за невидимую кровать."},"E474.3":{"s":"{{heroName}} выясняет, что предупреждение о плате никто не видел до сна, и требует отменить счета. Фея выплачивает золото.","f":"{{heroName}} не может доказать, что табличка не появлялась во сне, а Тилла взыскивает плату за разбирательство."},"E474.4":{"s":"Вы уходите, не обещая фее платить за сегодняшний сон. Кто-то уже опасается увидеть ночью зелёный фонтан."},"E475.1":{"s":"Вы осторожно проводите отряд под прозрачным ручьём, не потревожив плавающих над головой рыб.","f":"Вода внезапно опускается на дорогу, смывая часть припасов. Продолжить проход не удаётся."},"E475.2":{"s":"Вы платите феям за временный проход, и Ольви приподнимает поток выше повозок. Караван движется дальше."},"E475.3":{"s":"{{heroName}} укрепляет дорогу под воздушным ручьём, позволяя обозу пройти без опасности. В запасах остаются найденные припасы.","f":"Временная опора срывается, тяжело раня {{affectedHeroName}}.","v":{"nf":"Опора не выдерживает потока, но никто из подходящих бойцов не получает тяжёлого ранения. Проход приходится закрыть."}},"E475.4":{"s":"Вы тратите часть припасов на лесной обход, пока рыбы продолжают плавать над дорогой."},"E476.1":{"s":"Мира рассказывает, что в её ночном лесу прошло несколько лет, хотя дома минула лишь ночь. Родители благодарят золотом за спокойный разговор.","f":"Девочка пугается настойчивых вопросов и замолкает. Семья просит прекратить расспросы."},"E476.2":{"s":"Вы оставляете семье припасы на дорогу, и родители решают переждать странности вдали от колодца."},"E476.3":{"s":"{{heroName}} находит у колодца остатки магии смещённого времени, связанной с ночным возвращением девочки. Деревня благодарит золотом.","f":"Старая печать возле колодца отвечает ударом, тяжело раня {{affectedHeroName}}.","v":{"nf":"Печать срывает проверку, но никто из подходящих бойцов не получает тяжёлого ранения. Мира продолжает помнить то, чего ещё не было."}},"E476.4":{"s":"Вы не превращаете счастливое возвращение ребёнка в расследование перед соседями. Мира берёт родителей за руки возле старого колодца."},"E477.1":{"s":"Брен поёт неловко, но до конца, и Эсса принимает исполненный долг. Благодарная фея оставляет припасы.","f":"Брен снова предлагает золото вместо песни и не может заставить себя запеть. Эсса отказывается закрывать обещание."},"E477.2":{"s":"Эсса принимает вашу плату как замену обещанию, а Брен благодарит припасами за свободу от сорокалетнего долга.","f":"Фея не соглашается обменять песню на золото, и Брен остаётся должен прежнее."},"E477.3":{"s":"{{heroName}} находит короткую песню из трёх строк, которую Брен способен исполнить. Эсса благодарит золотом за услышанное.","f":"Брен сбивается даже на коротком куплете и просит отложить выступление. Фея ждёт."},"E477.4":{"s":"Вы оставляете Брена и Эссу обсуждать песню, обещанную сорок лет назад. Фея всё ещё отказывается от золота."},"E478.1":{"s":"Вы замечаете, что цветочные фигуры защищают путь к королевской клумбе, а садовница Пелли благодарит припасами за наблюдательность.","f":"Цветочная партия меняет расположение раньше, чем удаётся уловить закономерность. Правила остаются непонятны."},"E478.2":{"s":"Пелли продаёт вам съедобные растения для дороги, не трогая движущиеся шахматные клумбы."},"E478.3":{"s":"Король касается цветочной фигуры, и та раскрывает в земле золотой тайник. Остальные растения возвращаются к партии.","f":"Из листьев вырывается острая магия, причиняя Королю тяжёлое ранение.","v":{"nf":"Цветочная фигура отвечает опасной вспышкой, но Король не получает тяжёлого ранения. Тайник не открывается."}},"E478.4":{"s":"Вы оставляете фейский сад и его странную шахматную партию. Фигура в короне ещё долго смотрит вслед настоящему Королю."},"E479.1":{"s":"Вы снимаете ковёр с деревянного каркаса, и крестьяне узнают двух гоблинов внутри. Рикс возвращает деньги, часть которых достаётся отряду.","f":"Рикс зовёт вооружённых помощников, чтобы защитить свой «драконий» промысел. Начинается стычка."},"E479.2":{"s":"Вы покупаете у гоблинов настоящие припасы вместо услуг коврового дракона. Дым из деревянной пасти продолжает идти."},"E479.3":{"s":"{{heroName}} выводит каркас на площадь и показывает спрятанные ноги двух гоблинов. За разоблачение крестьяне платят золотом.","f":"Деревянный каркас обрушивается на {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Каркас обрушивается при проверке, но никто из подходящих бойцов не получает тяжёлого ранения. Рикс успевает скрыть устройство."}},"E479.4":{"s":"Вы оставляете рынок устрашающих услуг клиентам Рикса. Деревянный дракон за спиной громко кашляет печным дымом."},"E480.1":{"s":"Вы восстанавливаете настоящую ведомость Мока, и грабители возвращают кассу. Кассир платит золотом за защиту.","f":"Два охранника объявляют изъятие кассы частью своей работы и выходят на стычку."},"E480.2":{"s":"Вы вкладываете золото под выгодный процент и вовремя получаете прибыль после «реорганизации» банка.","f":"Внутреннее перераспределение захватывает и ваш вклад, который Зип объявляет добровольной премией."},"E480.3":{"s":"{{heroName}} обнаруживает поддельное разрешение на выдачу премий и заставляет вернуть золото в кассу. Мок благодарит за проверку.","f":"Зип предъявляет платный внутренний регламент, и отряду приходится отдать золото за бухгалтерское разбирательство."},"E480.4":{"s":"Вы не кладёте деньги в банк, где охрана грабит собственную кассу. Грабители всё ещё стоят в масках перед начальством."},"E481.1":{"s":"Вы убеждаете Пикса считать дополнительный счёт законным только при заранее согласованном тарифе. Гости благодарят золотом.","f":"Гоблин показывает подписи мелким шрифтом, и орк отказывается признавать даже их. Спор не заканчивается."},"E481.2":{"s":"Вы оплачиваете комнаты с ужином и получаете припасы на дорогу. Отряд договаривается не храпеть до предъявления рупора."},"E481.3":{"s":"{{heroName}} замечает, что Пикс подносил рупор к одному орку дважды, завысив счёт. Гоблин возвращает золото.","f":"Пикс предъявляет три подписи свидетелей и требует плату за ложное обвинение. Казна теряет золото."},"E481.4":{"s":"Вы ночуете под открытым небом, где никто не выставляет счёт за храп. В гостинице вновь звенит измерительный рупор."},"E482.1":{"s":"Вы прекращаете пуски переписных ракет и передаёте соседней крепости верный сигнал. Виз благодарит золотом за предотвращённую тревогу.","f":"Стража крепости принимает вашу попытку остановить перепись за враждебный сигнал. Начинается стычка."},"E482.2":{"s":"Вы продаёте переписчикам припасы вместо пороховых зарядов, а Виз платит золотом за помощь."},"E482.3":{"s":"{{heroName}} отделяет сигнальные ракеты от переписных и убирает опасные ящики. Город благодарит золотом.","f":"Один из ящиков вспыхивает во время разборки и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Заряд срабатывает опасно, но никто из подходящих бойцов не получает тяжёлого ранения. Перепись всё ещё пугает крепость."}},"E482.4":{"s":"Вы покидаете город до новой ракеты. На башне уже готовятся объявить прибытие Короля сигналом «пожар»."},"E483.1":{"s":"Вы проверяете работу совета и выясняете, что зерно исчезало со склада под отдельными печатями. Жители благодарят золотом за ревизию.","f":"Совет отказывается раскрывать расходы за правление Господина Уса. Зерно остаётся без объяснения."},"E483.2":{"s":"Вы продаёте городу зерновые припасы и получаете золото. Господин Ус лично осматривает первую доставку."},"E483.3":{"s":"{{heroName}} проводит заседание рядом с крысой и обнаруживает, что решения за неё принимал Флик. Совет платит золотом за возвращённую прозрачность.","f":"Флик объявляет заседание недостаточно законным и взыскивает плату за проверку. Казна теряет золото."},"E483.4":{"s":"Вы не вмешиваетесь в стабильную администрацию Господина Уса. Мэр тем временем уверенно исчезает в зерновом складе."},"E484.1":{"s":"Вы покупаете билет на будущие похороны Прука, а семья благодарит припасами за поддержку без обещания выступать с речью."},"E484.2":{"s":"Прук соглашается отдать семье часть выручки, пока ещё может сделать это сам. Он платит золотом за разумный совет.","f":"Прук утверждает, что доходы до похорон являются неприкосновенным бюджетом церемонии. Семье ничего не достаётся."},"E484.3":{"s":"Прук решает провести оставшееся время в путешествии, а не у собственной кассы. Он вступает в отряд.","f":"Прук не уверен, что сможет выдержать поход, и остаётся готовить церемонию.","v":{"rs":"Прук готов отправиться в поход, но свободного места нет. Он передаёт золото в знак признательности."}},"E484.4":{"s":"Вы не бронируете место на похоронах без назначенной даты. Прук уже обсуждает скидки за предварительную покупку."},"E485.1":{"s":"Вы приказываете Тамэлю и Ворсу тянуть одновременно, и человек наконец оказывается на земле. Благодарный спасённый платит золотом.","f":"Край обрыва осыпается под спасателями, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Край обрыва осыпается, но никто из подходящих бойцов не получает тяжёлого ранения. Спасение приходится продолжать другими средствами."}},"E485.2":{"s":"Вы используете припасы для верёвочной страховки и вытаскиваете человека независимо от спора ангела с демоном. Спасённый благодарит золотом."},"E485.3":{"s":"{{heroName}} закрепляет страховку на прочной скале и вытягивает человека до следующего обвала. Тамэль благодарит золотом.","f":"Верёвка срывается с опоры и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Страховка даёт опасную слабину, но никто из подходящих бойцов не получает тяжёлого ранения. Спасение не завершено."}},"E485.4":{"s":"Вы зовёте других путников с верёвками, не вмешиваясь в спор о заслугах. Тамэль и Ворс продолжают держать человека над обрывом."},"E486.1":{"s":"Сиэль поёт старую мелодию, и дверь сразу открывается без единого поворота рычага. Рокк раздражённо записывает наблюдение.","f":"Эльфийка забывает последний такт, и на лишнюю попытку уходят припасы. Дверь остаётся закрытой."},"E486.2":{"s":"Вы помогаете Рокку наладить противовесы, и дверь наконец открывается от рычага. Дварф платит золотом за доказанную механику.","f":"Шестерня срывается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Противовес срывает работу, но никто из подходящих бойцов не получает тяжёлого ранения. Дверь не открывается."}},"E486.3":{"s":"{{heroName}} находит мелодию, которая совпадает с ритмом шестерён, и дверь открывается. Рокк благодарит золотом и припасами.","f":"Внутренний замок отвечает резким ударом и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Замок срабатывает опасно, но никто из подходящих бойцов не получает тяжёлого ранения. Песню ещё не подобрали."}},"E486.4":{"s":"Вы обходите мастерскую по другой шахте, тратя припасы на переход. Сиэль продолжает напевать перед упрямой дверью."},"E487.1":{"s":"Ветераны делят обрывок штандарта пополам и впервые могут говорить без спора о трофее. Они благодарят припасами.","f":"Оба считают разрезание последним оскорблением памяти павших и не позволяют тронуть ткань. Мирного решения нет."},"E487.2":{"s":"Вы покупаете у ветеранов дорожные припасы, пока они продолжают вспоминать одну битву с разных сторон."},"E487.3":{"s":"Один из ветеранов решает, что ещё один поход лучше бесконечного спора у костра. Он вступает в отряд.","f":"Оба считают свою службу законченной и отказываются от нового похода.","v":{"rs":"Один из ветеранов готов служить, но взять нового бойца нельзя. На прощание он передаёт золото."}},"E487.4":{"s":"Вы оставляете двоих у одного костра разбирать прошлое. Штандарт лежит между ними, но руки больше не тянутся к оружию."},"E488.1":{"s":"Вы открываете кладбищенские ворота и находите золотой кошель у старого караульного камня. Вороны перестают клевать решётку.","f":"Из кладбища выходят вооружённые мертвецы, которых птицы удерживали за оградой. Начинается битва."},"E488.2":{"s":"Вы оставляете Сену припасы на укрепление ограды, а могильщик платит золотом за помощь. Вороны продолжают сторожить выход."},"E488.3":{"s":"{{heroName}} обнаруживает старую печать, из-за которой вороны удерживают нежить внутри. Сен благодарит золотом за разгадку.","f":"Печать отвечает магическим ударом и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Печать останавливает исследователей, но никто из подходящих бойцов не получает тяжёлого ранения. Птицы продолжают охрану."}},"E488.4":{"s":"Вы не вмешиваетесь в работу вороньей стражи. Скелет машет на них надгробной табличкой без особого успеха."},"E489.1":{"s":"Вы выключаете М-9 до следующей попытки продать Физа как товар. Гоблин благодарит золотом за спасённую работу.","f":"Боковая дверца захлопывается во время отключения и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Механизм опасно срабатывает, но никто из подходящих бойцов не получает тяжёлого ранения. М-9 остаётся включённым."}},"E489.2":{"s":"Вы покупаете у М-9 припасы и проверяете, что вместо сдачи не выдали самого Физа."},"E489.3":{"s":"{{heroName}} исправляет сортировщик монет и освобождает Физа от обязанности выходить из автомата. Мастер платит золотом и припасами.","f":"Пружина выдачи срывается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Пружина срывает ремонт, но никто из подходящих бойцов не получает тяжёлого ранения. Физ по-прежнему ждёт внутри."}},"E489.4":{"s":"Вы отходите от М-9, не проверяя его оценку Короля. Физ закрывает боковую дверцу с явным облегчением."},"E490.1":{"s":"Вы убеждаете Ним вернуть украденное имя, и паук впервые откликается на зов Саиры. Хозяйка благодарит золотом.","f":"Ним зовёт фейских приятелей защищать её право на игру. Начинается стычка."},"E490.2":{"s":"Вы оплачиваете Ним прекращение игры, и она возвращает пауку имя. Саира благодарит припасами."},"E490.3":{"s":"{{heroName}} обучает Саиру управлять пауком жестами, пока имя не возвращено. Хозяйка благодарит золотом.","f":"Паук резко разворачивается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Паук отказывается идти за жестами, но никто из подходящих бойцов не получает тяжёлого ранения. Имя всё ещё у феи."}},"E490.4":{"s":"Вы оставляете Ним владеть чужим именем. Паук молча поворачивается на звук, который теперь не узнаёт."},"E491.1":{"s":"Бем признаёт драконье пламя отдельной частью труда, а Корас соглашается снова разжигать горн. Кузница платит золотом за законченный спор.","f":"Бем продолжает считать дыхание бесплатным инструментом и оставляет горн остывать. Договор не заключён."},"E491.2":{"s":"Вы покупаете у кузницы припасы, пока мастера спорят о цене одного выдоха. Корас демонстративно не смотрит на горн."},"E491.3":{"s":"{{heroName}} разделяет стоимость металла, ковки и драконьего огня в общей ведомости. Оба мастера принимают расчёт и платят золотом.","f":"{{heroName}} не может договориться о стоимости дыхания, а за экспертизу кузница взыскивает золото."},"E491.4":{"s":"Вы не решаете, кому принадлежит огонь после выдоха. Бем пытается разжечь холодный горн обычным углём."},"E492.1":{"s":"Мэй и Хорн сами выходят на арену, а дети хлопают до конца представления. Артисты делятся золотом из новой выручки.","f":"Под шатром ломается крепление, и труппе приходится отменить номер. Детям возвращают деньги, а касса остаётся пустой."},"E492.2":{"s":"Вы оставляете артистам припасы на два следующих дня, а они благодарят золотом из последней кассы. Мэй впервые предлагает выступать без хозяина."},"E492.3":{"s":"{{heroName}} организует сбор платы у входа и держит кассу на виду у всей труппы. Артисты выдают золото за честную помощь.","f":"В суматохе кто-то уносит часть выручки, и казна отряда теряет золото при попытке возместить недостачу."},"E492.4":{"s":"Вы оставляете цирк решать, продолжать ли путь без хозяина. Дети уже занимают лучшие места у шатра."},"E493.1":{"s":"Вы помогаете Эраю выкопать могилу, и неподвижные скелеты уступают место без боя. Ангел благодарит припасами за достойное погребение.","f":"Скелеты не доверяют живым даже с лопатами, и похороны откладываются. Никто не поднимает оружия."},"E493.2":{"s":"Вы оставляете припасы тем, кто будет сторожить погребение, а Эрай благодарит золотом за помощь."},"E493.3":{"s":"{{heroName}} проводит обряд, одинаково уважающий клятву Эрая и верность скелетов. Ангел выдаёт золото за завершённое прощание.","f":"Старая защита тела отвечает ударом и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Погребальная печать срывает обряд, но никто из подходящих бойцов не получает тяжёлого ранения. Могила остаётся пустой."}},"E493.4":{"s":"Вы оставляете Эрая и скелетов у тела старого врага. Они молча стоят рядом, всё ещё не решаясь начать похороны."},"E494.1":{"s":"Вы отдаёте Ураку три монеты нужной чеканки, и Снип наконец закрывает долг. Гоблин благодарит припасами за точный расчёт."},"E494.2":{"s":"Вы убеждаете Снипа принять равную стоимость другими монетами, и Урак платит золото за прекращённую шестимесячную погоню.","f":"Снип отказывается признавать замену трём точным монетам. Договор остаётся непогашенным."},"E494.3":{"s":"{{heroName}} находит разрешение на равнозначный платёж, не нарушающее условия о трёх монетах. Демон благодарит золотом.","f":"Снип предъявляет обязательную плату за новый расчёт, и отряд теряет золото, пока спор продолжается."},"E494.4":{"s":"Вы не вмешиваетесь в долг, который Урак готов переплатить тридцать раз. Снип снова достаёт старую расписку."},"E495.1":{"s":"Сиан принимает год без охоты и передаёт оружие младшим, а община благодарит отряд припасами за уважение к обычаю.","f":"Старейшины требуют отложить обет из-за зимы, и решение раскалывает охотничий совет."},"E495.2":{"s":"Вы отдаёте общине припасы на время без лучшей охотницы, и Сиан благодарит золотом за поддержку."},"E495.3":{"s":"{{heroName}} находит старое правило о передаче годового обета по согласию общины, не нарушая священного знака. Совет благодарит золотом.","f":"{{heroName}} не находит признанного исключения, и совет оставляет Сиан перед трудным выбором."},"E495.4":{"s":"Вы не решаете, чего хотел священный олень. Он спокойно лежит у ног Сиан, пока охотники спорят."},"E496.1":{"s":"Вы расчищаете безопасный проход мимо гигантского цветка, не разрушая корней. Орки снабжают отряд припасами.","f":"Стебель резко распрямляется и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Корни отбрасывают инструменты, но никто из подходящих бойцов не получает тяжёлого ранения. Проход остаётся закрытым."}},"E496.2":{"s":"Соль продаёт вам съедобные части огромного растения, и припасы отправляются в обоз. Орки по-прежнему готовят катапульту."},"E496.3":{"s":"{{heroName}} прокладывает тропу по краю бывшего поля боя, не потревожив цветок. Орки благодарят золотом и припасами.","f":"При обходе обрушивается земля, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Земля проседает под работами, но никто из подходящих бойцов не получает тяжёлого ранения. Обход приходится отложить."}},"E496.4":{"s":"Вы уезжаете до первого в истории штурма цветка. Фея Соль ещё пытается объяснить оркам, что растение не объявляло войну."},"E497.1":{"s":"Вы находите заказчика, и тот признаёт, что имел в виду отключение О-6, а не убийство. Шира платит золотом за уточнение договора.","f":"Заказчик направляет вооружённых помощников, чтобы не обсуждать с исполнителем смысл заказа. Начинается стычка."},"E497.2":{"s":"О-6 принимает предложение уйти с Королём, пока заказчик не решит, что такое убийство машины. Автомат вступает в отряд.","f":"О-6 отказывается скрываться и хочет добиться ясного решения по договору. Нанять его не удаётся.","v":{"rs":"О-6 готов уйти с отрядом, но свободного места нет. Он благодарит золотом и остаётся ждать решения."}},"E497.3":{"s":"{{heroName}} доказывает, что юридическое понятие убийства не описывает разрушение автомата. Гильдия закрывает контракт и платит золотом.","f":"Заказчик показывает особую оговорку в контракте и взыскивает плату за его пересмотр. Казна теряет золото."},"E497.4":{"s":"Вы уходите, не определяя убийство для Ширы и О-6. Автомат продолжает требовать уточнения термина."},"E498.1":{"s":"Вы перехватываете гуся у прилавка дварфа и находите на кошеле метку настоящего владельца. Благодарный торговец выдаёт золото.","f":"Преследователи гуся принимают вас за нового похитителя и хватаются за оружие. Начинается стычка."},"E498.2":{"s":"Вы закупаете дорожные припасы у нескольких народов, пока гусь продолжает гонку между прилавками."},"E498.3":{"s":"Один из свободных путешественников охотно меняет рынок на королевский поход и вступает в отряд.","f":"Свободные путники предпочитают завершить ярмарку прежде, чем соглашаться на службу. Нанять никого не удаётся.","v":{"rs":"Новый спутник согласен идти, но места для него нет. Он вручает золото в знак благодарности за предложение."}},"E498.4":{"s":"Вы проходите рынок четырнадцати народов, не купив ничего. Гусь успевает пересечь дорогу ещё раз с чужим кошелём."},"E499.1":{"s":"Живой и призрачный Берты соглашаются временно делить должность, пока совет не решит вопрос законно. Горожане благодарят припасами.","f":"Каждый Берт требует единоличную подпись на приказах и отказывается признавать другого. Совет не получает нового решения."},"E499.2":{"s":"Вы оставляете городскому совету самостоятельно определить полномочия двух Бертов. Оба мэра тут же требуют председательствовать на заседании."},"E499.3":{"s":"{{heroName}} сопоставляет время смерти, возвращения призрака и оживления тела с городским уставом. Совет платит золотом за правовой вывод.","f":"{{heroName}} находит пробел в уставе о возвращении сразу в двух состояниях, а канцелярия взыскивает пошлину. Отряд теряет золото."},"E499.4":{"s":"Вы уезжаете до появления третьего Берта. За спиной два мэра одновременно подписывают несовместимые распоряжения."},"E500.1":{"s":"Вы остаетесь у костра до рассвета и замечаете, как лишнее место занимает невидимый путник. На его следах находят забытый кошель с золотом.","f":"Когда пятнадцатая миска опустеет, из темноты выходят вооружённые невидимые гости. Начинается битва."},"E500.2":{"s":"Вы спешно снимаете лагерь, теряя часть провизии в дороге. Позади остаются четырнадцать пустых мест и одно, которого никто не видел."},"E500.3":{"s":"{{heroName}} идёт по лишним отпечаткам и обнаруживает спрятанный дорожный кошель и припасы. Следы обрываются прямо возле отряда.","f":"Невидимый путник наносит внезапный удар, тяжело раня {{affectedHeroName}}.","v":{"nf":"Невидимый гость срывает разведку, но никто из подходящих бойцов не получает тяжёлого ранения. Лишняя миска остаётся полной."}},"E500.4":{"s":"Вы оставляете пятнадцатую порцию у костра и уходите утром, не выясняя, кому она предназначалась. На влажной земле появляется ещё один шаг."}});
export { OUTCOMES_E431_E500 };
